from pathlib import Path
import re, sys
root=Path(sys.argv[1] if len(sys.argv)>1 else '.').resolve()
main=root/'app/main.py'; html=root/'app/static/index.html'; js=root/'app/static/app.js'; css=root/'app/static/style.css'
for p in (main,html,js,css):
    if not p.exists(): raise SystemExit(f'Missing expected file: {p}')

m=main.read_text(encoding='utf-8')
if 'ARLAW_CHAT_HISTORY_API' not in m:
    m += '''\n\n# ARLAW_CHAT_HISTORY_API: SQLite-backed conversation history\nimport os as _h_os, sqlite3 as _h_sqlite3, uuid as _h_uuid\nfrom datetime import datetime as _h_datetime, timezone as _h_timezone\nfrom fastapi import Body as _h_Body\n_HISTORY_DB=Path(_h_os.getenv('ARLAW_CHAT_DB',str(Path(__file__).resolve().parent/'data'/'chat_history.sqlite3')))\n_HISTORY_DB.parent.mkdir(parents=True,exist_ok=True)\ndef _h_conn():\n    c=_h_sqlite3.connect(str(_HISTORY_DB),timeout=15); c.row_factory=_h_sqlite3.Row; return c\nwith _h_conn() as c:\n    c.execute('CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY,title TEXT NOT NULL,messages TEXT NOT NULL,jurisdiction TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)')\n@app.get('/api/conversations')\ndef history_list():\n    with _h_conn() as c: rows=c.execute('SELECT id,title,jurisdiction,created_at,updated_at FROM conversations ORDER BY updated_at DESC').fetchall()\n    return {'conversations':[dict(x) for x in rows]}\n@app.get('/api/conversations/{conversation_id}')\ndef history_get(conversation_id:str):\n    with _h_conn() as c: row=c.execute('SELECT * FROM conversations WHERE id=?',(conversation_id,)).fetchone()\n    if row is None: raise HTTPException(404,'Conversation not found')\n    item=dict(row); item['messages']=json.loads(item['messages']); return item\n@app.put('/api/conversations/{conversation_id}')\ndef history_save(conversation_id:str,payload:dict=_h_Body(...)):\n    try: cid=str(_h_uuid.UUID(conversation_id))\n    except ValueError: raise HTTPException(400,'Invalid conversation ID')\n    msgs=payload.get('messages')\n    if not isinstance(msgs,list) or not msgs or len(msgs)>300: raise HTTPException(422,'Invalid messages')\n    clean=[]\n    for x in msgs:\n        if not isinstance(x,dict) or x.get('role') not in ('user','assistant') or not isinstance(x.get('content'),str) or len(x['content'])>14000: raise HTTPException(422,'Invalid message')\n        clean.append({'role':x['role'],'content':x['content']})\n    title=next((x['content'].strip() for x in clean if x['role']=='user'),'New chat')[:72] or 'New chat'\n    jurisdiction=str(payload.get('jurisdiction') or 'GLOBAL')[:80]; now=_h_datetime.now(_h_timezone.utc).isoformat()\n    with _h_conn() as c:\n        old=c.execute('SELECT created_at FROM conversations WHERE id=?',(cid,)).fetchone(); created=old['created_at'] if old else now\n        c.execute('INSERT INTO conversations VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,messages=excluded.messages,jurisdiction=excluded.jurisdiction,updated_at=excluded.updated_at',(cid,title,json.dumps(clean,ensure_ascii=False),jurisdiction,created,now))\n    return {'ok':True,'id':cid,'title':title}\n@app.delete('/api/conversations/{conversation_id}')\ndef history_delete(conversation_id:str):\n    with _h_conn() as c: cur=c.execute('DELETE FROM conversations WHERE id=?',(conversation_id,))\n    if not cur.rowcount: raise HTTPException(404,'Conversation not found')\n    return {'ok':True}\n'''
    main.write_text(m,encoding='utf-8')

h=html.read_text(encoding='utf-8')
if 'id="historyToggle"' not in h:
    h=h.replace('<button id="newChat" class="new"><span>＋</span> New chat</button>','<button id="newChat" class="new"><span>＋</span> New chat</button>\n    <button id="historyToggle" class="nav history-toggle" type="button">◷ Chat history</button>\n    <div id="historyList" class="history-list" aria-live="polite"><small>Loading…</small></div>')
if 'history.js' not in h: h=h.replace('<script src="/static/app.js"></script>','<script src="/static/app.js"></script><script src="/static/history.js"></script>')
html.write_text(h,encoding='utf-8')

j=js.read_text(encoding='utf-8')
if 'ARLAW_HISTORY_SAVE_HOOK' not in j:
    pattern=r'async function send\(text\)\{.*?\n?\}'
    match=re.search(pattern,j,re.S)
    if not match: raise SystemExit('Could not safely locate send(text) in app.js')
    replacement='''async function send(text){\n if(!text.trim())return;history.push({role:"user",content:text});add("user",text);\n try{let r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({messages:history,jurisdiction:$("jurisdiction").value})});let d=await r.json();if(!r.ok)throw Error(d.detail||"Request failed");history.push({role:"assistant",content:d.answer});add("assistant",d.answer,d.citations||[]);if(d.quality_warning)add("assistant","Reliability warning: "+d.quality_warning);$("connection").textContent=d.model_connected?`${d.model?.provider||"AI"} · ${d.model?.model||"connected"} · ${d.task||"general"}`:"Model unavailable";if(d.model_connected&&window.ARLAWHistory)await window.ARLAWHistory.persist();}\n catch(e){add("assistant","Application error: "+e.message)}\n}\n// ARLAW_HISTORY_SAVE_HOOK'''
    j=j[:match.start()]+replacement+j[match.end():]
    j=j.replace('$("newChat").onclick=()=>{history=[];','$("newChat").onclick=()=>{if(window.ARLAWHistory)window.ARLAWHistory.startNew();history=[];')
    js.write_text(j,encoding='utf-8')

history_js=r'''(()=>{const $=id=>document.getElementById(id);let currentId=null;const list=$('historyList');const newId=()=>crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{let r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});async function refresh(){try{let r=await fetch('/api/conversations');let d=await r.json();list.innerHTML='';if(!d.conversations.length){list.textContent='No saved conversations yet.';return}d.conversations.forEach(x=>{let row=document.createElement('div');row.className='history-row';let b=document.createElement('button');b.className='history-open';b.textContent=x.title;b.onclick=()=>load(x.id);let del=document.createElement('button');del.className='history-delete';del.textContent='×';del.title='Delete';del.onclick=async()=>{if(confirm('Delete this conversation?')){await fetch('/api/conversations/'+x.id,{method:'DELETE'});if(currentId===x.id){currentId=null;history=[];document.getElementById('newChat').click()}refresh()}};row.append(b,del);list.append(row)})}catch(e){list.textContent='History unavailable; check server connection.'}}async function persist(){if(!history.length)return;if(!currentId)currentId=newId();let r=await fetch('/api/conversations/'+currentId,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:history,jurisdiction:$('jurisdiction').value})});if(!r.ok)throw Error('History could not be saved');refresh()}async function load(id){let r=await fetch('/api/conversations/'+id);if(!r.ok)return alert('Could not open conversation');let x=await r.json();currentId=id;history=x.messages||[];$('messages').innerHTML='';history.forEach(m=>window.add(m.role,m.content));$('chatView').classList.remove('hidden');$('sourcesView').classList.add('hidden');$('supportView').classList.add('hidden');$('chatTab').classList.add('active');$('sourcesTab').classList.remove('active');$('supportTab').classList.remove('active');$('jurisdiction').value=x.jurisdiction||'GLOBAL'}function startNew(){currentId=null;refresh()}$('historyToggle')?.addEventListener('click',()=>{list.classList.toggle('expanded');refresh()});window.ARLAWHistory={persist,refresh,startNew};refresh()})();'''
(root/'app/static/history.js').write_text(history_js,encoding='utf-8')

c=css.read_text(encoding='utf-8')
if '.history-list{' not in c: c+='''\n/* ARLAW chat history */\n.history-list{display:none;max-height:36vh;overflow:auto;margin:4px 0 12px 8px;padding-right:4px}.history-list.expanded{display:block}.history-row{display:flex;gap:4px;margin:3px 0}.history-open{flex:1;min-width:0;text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:transparent;border:0;border-radius:8px;padding:9px;color:inherit;cursor:pointer}.history-delete{border:0;background:transparent;color:inherit;padding:5px 9px;cursor:pointer}\n'''; css.write_text(c,encoding='utf-8')
print('Installed Chat History patch in',root)
